<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { useRoute } from 'vue-router';
import { ArrowLeft, ArrowRight, CircleCheck, LifeBuoy, LoaderCircle, LockKeyhole, MessageSquare, Paperclip, Plus, RefreshCw, Search, Send, X } from 'lucide-vue-next';
import PageHeading from '../components/PageHeading.vue';
import { saveSupportDraft, takeSupportDraft } from '../lib/supportDraft';
import { usePanelContext } from '../composables/panelContext';
import { useCommerce, stamp, stateText, type Ticket, type TicketReply } from '../lib/commerce';
import { mergeHistory } from '../components/member/flow';
import { serialPoll } from '../lib/requests';
import { t } from '../i18n';
import '../commerce.css';
import '../styles/member-ui.css';
const route=useRoute(),{owner,state}=usePanelContext(),{read,run,api,busy,error,notice}=useCommerce('/support');
const items=ref<Ticket[]>([]),ticket=ref<Ticket|null>(null),replies=ref<TicketReply[]>([]),activeID=ref('');
const creating=ref(!!route.query.order),title=ref(''),body=ref(''),category=ref(route.query.order?'order':'node'),orderID=ref(String(route.query.order||'')),resource=ref(''),resources=ref<{site_id:string;node_id:string;name:string}[]>([]),internal=ref(false),attachments=ref<string[]>([]);
const uploading=ref(false),nextState=ref(''),priority=ref('normal'),loading=ref(true),detailLoading=ref(false),detailReady=ref(false),loadingMore=ref(false),loadingOlder=ref(false),hasMore=ref(false),hasOlder=ref(false),filter=ref('all'),query=ref('');
const filters=[{id:'all',label:'全部工单'},{id:'active',label:'处理中'},{id:'waiting_user',label:'待用户回复'},{id:'done',label:'已结束'}];
const visible=computed(()=>items.value.filter(v=>(filter.value==='all'||(filter.value==='active'?['open','processing'].includes(v.state):filter.value==='done'?['closed','resolved'].includes(v.state):v.state===filter.value))&&(!query.value.trim()||[v.title,v.id,v.order_id,v.resource,owner.value?String(v.user_id):''].join(' ').toLowerCase().includes(query.value.trim().toLowerCase()))));
const ticketState=(value:string)=>!owner.value&&value==='waiting_user'?t('待你回复'):stateText(value);
const conversation=computed(()=>[...replies.value].reverse());
const finished=computed(()=>!!ticket.value&&['closed','resolved'].includes(ticket.value.state));
const canReopen=computed(()=>!!ticket.value&&finished.value&&ticket.value.closed>0&&Date.now()/1000-ticket.value.closed<=7*86400);
const statusDirty=computed(()=>!!ticket.value&&(nextState.value!==ticket.value.state||priority.value!==ticket.value.priority));
const composerVisible=computed(()=>creating.value||!!ticket.value&&!finished.value&&detailReady.value);
const imageURL=(id:string)=>'/api/support/attachment?id='+encodeURIComponent(id);
type Draft={title:string;body:string;category:string;orderID:string;resource:string;internal:boolean;attachments:string[];saved:number};
const drafts=new Map<string,Draft>();
function stash(){const key=creating.value?'create':activeID.value;if(!key)return;drafts.set(key,{title:title.value,body:body.value,category:category.value,orderID:orderID.value,resource:resource.value,internal:internal.value,attachments:[...attachments.value],saved:Date.now()})}
function restore(key:string){const draft=drafts.get(key);title.value=draft?.title||'';body.value=draft?.body||'';category.value=draft?.category||'node';orderID.value=draft?.orderID||'';resource.value=draft?.resource||'';internal.value=draft?.internal||false;attachments.value=draft&&Date.now()-draft.saved<15*60000?[...draft.attachments]:[];}
let listSequence=0,detailSequence=0,conversationEpoch=0,expandedList=false,expandedReplies=false,disposed=false;
async function load(manual=false){const sequence=++listSequence;if(manual){loading.value=true;error.value=''}try{const value=await read<{items:Ticket[]}>('/tickets');if(sequence===listSequence&&value&&!disposed){items.value=mergeHistory(items.value,value.items);if(!expandedList)hasMore.value=value.items.length>=50}}finally{if(sequence===listSequence)loading.value=false}}
async function detail(id:string,foreground=false){
  const sequence=++detailSequence,epoch=conversationEpoch;if(foreground)detailLoading.value=true;
  try{const value=await read<{ticket:Ticket;replies:TicketReply[]}>('/ticket?id='+encodeURIComponent(id));if(!value||disposed||sequence!==detailSequence||epoch!==conversationEpoch||activeID.value!==id)return;const same=ticket.value?.id===id,keepStatus=same&&detailReady.value&&statusDirty.value;ticket.value=value.ticket;replies.value=same?mergeHistory(replies.value,value.replies):value.replies;if(!expandedReplies)hasOlder.value=value.replies.length>=50;if(!keepStatus){nextState.value=value.ticket.state;priority.value=value.ticket.priority}detailReady.value=true;items.value=mergeHistory(items.value,[value.ticket]);}
  finally{if(sequence===detailSequence&&epoch===conversationEpoch)detailLoading.value=false}
}
async function open(value:Ticket){if(busy.value||uploading.value)return;stash();conversationEpoch++;detailSequence++;activeID.value=value.id;ticket.value=value;creating.value=false;replies.value=[];detailReady.value=false;expandedReplies=false;hasOlder.value=false;loadingOlder.value=false;nextState.value=value.state;priority.value=value.priority;restore(value.id);error.value='';notice.value='';await detail(value.id,true)}
async function more(){const last=items.value.at(-1);if(!last||loadingMore.value)return;loadingMore.value=true;try{const value=await read<{items:Ticket[]}>('/tickets?before='+encodeURIComponent(last.id));if(value&&!disposed){items.value=mergeHistory(items.value,value.items);hasMore.value=value.items.length>=50;expandedList=true}}finally{loadingMore.value=false}}
async function older(){const last=replies.value.at(-1),id=activeID.value,epoch=conversationEpoch;if(!last||!id||loadingOlder.value)return;loadingOlder.value=true;try{const value=await read<{replies:TicketReply[]}>('/ticket?id='+encodeURIComponent(id)+'&before='+encodeURIComponent(last.id));if(value&&!disposed&&epoch===conversationEpoch&&activeID.value===id){replies.value=mergeHistory(replies.value,value.replies);hasOlder.value=value.replies.length>=50;expandedReplies=true}}finally{if(epoch===conversationEpoch)loadingOlder.value=false}}
async function submit(){
  if(busy.value||uploading.value||!body.value.trim()||(!creating.value&&!detailReady.value))return;
  const [site_id='',node_id='']=resource.value.split('/'),wasCreating=creating.value,previousKey=wasCreating?'create':activeID.value;
  const value=wasCreating?await run<Ticket>('/tickets',{title:title.value,body:body.value,category:category.value,order_id:orderID.value,site_id,node_id,attachments:attachments.value}):await run<Ticket>('/reply',{id:activeID.value,body:body.value,internal:internal.value,attachments:attachments.value});
  if(!value||disposed)return;
  // A successful write remains visible even if the following read fails.
  drafts.delete(previousKey);notice.value=wasCreating?t('问题已提交，我们会在这里回复。'):t('回复已发送');creating.value=false;activeID.value=value.id;ticket.value=value;if(wasCreating){replies.value=[];expandedReplies=false}nextState.value=value.state;priority.value=value.priority;body.value='';title.value='';attachments.value=[];internal.value=false;resource.value='';detailReady.value=true;items.value=mergeHistory(items.value,[value]);await detail(value.id,true);await load();
}
async function status(target?:string){
  if(!ticket.value||busy.value||uploading.value)return;busy.value=true;error.value='';notice.value='';
  try{const value=await api<Ticket>('/state','POST',{id:ticket.value.id,revision:ticket.value.revision,state:target||nextState.value,priority:priority.value});if(disposed)return;ticket.value=value;nextState.value=value.state;priority.value=value.priority;items.value=mergeHistory(items.value,[value]);notice.value=t('工单状态已更新');await detail(value.id);await load()}
  catch(reason){error.value=reason instanceof Error?t(reason.message):t('请求失败')}
  finally{busy.value=false}
}
const fileData=(file:File)=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error(t('图片读取失败')));reader.readAsDataURL(file)});
async function upload(event:Event){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(files.length+attachments.value.length>3){error.value=t('每次最多上传 3 张图片');return}uploading.value=true;error.value='';try{for(const file of files){if(file.size>2*1024*1024||!['image/png','image/jpeg'].includes(file.type)||! /\.(png|jpe?g)$/i.test(file.name))throw new Error(t('仅允许 PNG/JPG 图片，每张最大 2 MiB'));const value=await api<{id:string}>('/upload','POST',{name:file.name,mime:file.type,data:await fileData(file)});if(disposed)return;attachments.value.push(value.id)}}catch(reason){error.value=reason instanceof Error?t(reason.message):t('请求失败')}finally{uploading.value=false}}
function back(){if(busy.value||uploading.value)return;stash();conversationEpoch++;detailSequence++;activeID.value='';ticket.value=null;creating.value=false;detailReady.value=false;detailLoading.value=false;loadingOlder.value=false;body.value='';attachments.value=[];}
function create(){if(busy.value||uploading.value||creating.value)return;stash();conversationEpoch++;detailSequence++;ticket.value=null;activeID.value='';creating.value=true;detailReady.value=false;detailLoading.value=false;loadingOlder.value=false;restore('create');error.value='';notice.value='';}
const poll=serialPoll(async()=>{if(document.hidden||busy.value||uploading.value||loading.value||loadingMore.value||loadingOlder.value||detailLoading.value)return;if(activeID.value)await detail(activeID.value);await load()},()=>15000);
onMounted(async()=>{const draft=!route.query.order?takeSupportDraft(state.value?.me.id||0):null;if(draft){creating.value=draft.creating;title.value=draft.title;body.value=draft.body;category.value=draft.category;orderID.value=draft.orderID;resource.value=draft.resource;internal.value=draft.internal;attachments.value=draft.attachments;if(draft.ticketID){activeID.value=draft.ticketID;await detail(draft.ticketID,true)}}await load();const value=await read<{items:typeof resources.value}>('/resources');if(value)resources.value=value.items;if(!disposed)poll.start()});
onUnmounted(()=>{disposed=true;poll.stop();listSequence++;detailSequence++;conversationEpoch++;saveSupportDraft(state.value?.me.id||0,{ticketID:activeID.value,creating:creating.value,title:title.value,body:body.value,category:category.value,orderID:orderID.value,resource:resource.value,internal:internal.value,attachments:attachments.value,saved:Date.now()})});
</script>
<template>
  <section class="commerce-page member-page tickets-page">
    <PageHeading :title="owner?t('工单中心'):t('帮助与支持')" :description="t('描述遇到的问题，处理进度与回复都会保留在这里。')" eyebrow="SUPPORT"><template #actions><button v-if="ticket||creating||activeID" :disabled="busy||uploading" @click="back"><ArrowLeft :size="16"/>{{t('返回工单列表')}}</button><button :disabled="loading||detailLoading||busy||uploading" @click="activeID?detail(activeID,true):load(true)"><RefreshCw :size="16" :class="{spin:loading||detailLoading}"/>{{t('刷新')}}</button><button v-if="!creating" class="primary" :disabled="busy||uploading" @click="create"><Plus :size="16"/>{{t('新建工单')}}</button></template></PageHeading>
    <p v-if="error" class="error member-feedback" role="alert">{{error}}</p><p v-if="notice&&!composerVisible" class="member-feedback" role="status"><CircleCheck :size="17"/>{{notice}}</p>
    <div class="support-workspace" :class="{'has-conversation':!!activeID||creating}">
      <aside class="member-panel ticket-directory" :aria-label="t('工单列表')" :aria-busy="loading"><div class="ticket-directory-heading"><h2>{{t('工单列表')}}</h2><span class="member-label">{{items.length}}</span></div><label class="member-search"><Search :size="16"/><input v-model="query" type="search" :placeholder="t('搜索标题或工单号')" :aria-label="t('搜索标题或工单号')"/></label><div class="ticket-filters" role="group" :aria-label="t('工单状态')"><button v-for="item in filters" :key="item.id" :aria-pressed="filter===item.id" @click="filter=item.id">{{!owner&&item.id==='waiting_user'?t('待我回复'):t(item.label)}}</button></div>
        <div v-if="loading&&!items.length" class="ticket-list-empty" role="status"><LoaderCircle :size="23" class="spin"/><p>{{t('正在加载记录…')}}</p></div><div v-else-if="!visible.length&&!error" class="ticket-list-empty"><MessageSquare :size="28"/><h3>{{items.length?t('没有匹配的工单'):t('暂无工单')}}</h3><p>{{items.length?t('试试其他名称或筛选条件。'):t('遇到使用问题时，可提交工单联系管理员。')}}</p><button v-if="filter!=='all'||query" @click="filter='all';query=''">{{t('清除筛选')}}</button></div>
        <div class="ticket-list"><button v-for="item in visible" :key="item.id" :class="['ticket-list-row',{selected:activeID===item.id&&!creating}]" :aria-pressed="activeID===item.id&&!creating" :disabled="busy||uploading" @click="open(item)"><span class="ticket-list-title">{{item.title}}</span><span class="ticket-list-meta"><span :class="['member-status',item.state]">{{ticketState(item.state)}}</span><span v-if="item.priority==='urgent'" class="ticket-urgent">{{t('紧急')}}</span></span><span class="ticket-list-time">{{stamp(item.updated)}}<template v-if="owner"> · #{{item.user_id}}</template></span></button></div><div v-if="hasMore" class="ticket-pagination"><p>{{t('筛选仅作用于已加载工单，可继续加载更多。')}}</p><button :disabled="loadingMore||loading" @click="more"><LoaderCircle v-if="loadingMore" :size="16" class="spin"/>{{t('加载更多')}}</button></div>
      </aside>
      <div class="support-detail">
        <div v-if="!activeID&&!creating" class="member-panel support-welcome"><span><LifeBuoy :size="32"/></span><h2>{{t('有什么可以帮你？')}}</h2><p>{{t('选择左侧工单继续沟通，或告诉我们你遇到的新问题。')}}</p><button class="primary" @click="create"><Plus :size="17"/>{{t('新建工单')}}</button><RouterLink class="member-link" to="/subscription?connect=1">{{t('先看看连接向导')}}<ArrowRight :size="16"/></RouterLink></div>
        <div v-if="activeID&&detailLoading&&!detailReady" class="member-panel member-empty" role="status"><LoaderCircle :size="25" class="spin"/><p>{{t('正在读取对话…')}}</p></div><div v-else-if="activeID&&!detailReady" class="member-panel member-empty"><MessageSquare :size="28"/><h2>{{t('对话暂不可用')}}</h2><button :disabled="detailLoading" @click="detail(activeID,true)">{{t('重试')}}</button></div>
        <template v-if="ticket&&detailReady">
          <article class="member-panel ticket-summary"><div class="member-panel-title"><div><span class="member-label">{{t('工单')}} · {{stamp(ticket.created)}}</span><h2>{{ticket.title}}</h2></div><span :class="['member-status',ticket.state]">{{ticketState(ticket.state)}}</span></div><details class="ticket-metadata"><summary>{{t('关联信息与工单号')}}</summary><p class="commerce-id">{{ticket.id}}</p><p v-if="ticket.resource" class="member-label">{{ticket.resource}}</p><p v-if="ticket.order_id" class="member-label">{{t('关联订单')}} <RouterLink :to="{path:'/orders',query:{checkout:ticket.order_id,...(owner?{user_id:ticket.user_id}:{})}}">{{ticket.order_id}}</RouterLink></p><p v-if="owner" class="member-label">{{t('用户')}} #{{ticket.user_id}}</p></details><form v-if="owner" class="ticket-state-form" @submit.prevent="status()"><label>{{t('工单状态')}}<select v-model="nextState" :disabled="busy"><option value="open">{{t('待处理')}}</option><option value="processing">{{t('处理中')}}</option><option value="waiting_user">{{t('待用户回复')}}</option><option value="resolved">{{t('已解决')}}</option><option value="closed">{{t('已关闭')}}</option></select></label><label>{{t('优先级')}}<select v-model="priority" :disabled="busy"><option value="normal">{{t('普通')}}</option><option value="urgent">{{t('紧急')}}</option></select></label><button :disabled="busy||!statusDirty">{{busy?t('处理中…'):t('更新状态')}}</button></form><div v-else class="member-actions ticket-member-actions"><button v-if="!finished" :disabled="busy||uploading" @click="status('closed')">{{t('问题已解决，关闭工单')}}</button><button v-else-if="canReopen" :disabled="busy||uploading" @click="status('open')">{{t('问题仍在，重新打开')}}</button><p v-else class="member-label">{{t('此工单已结束，如需继续请新建工单并注明原工单号。')}}</p></div></article>
          <div class="conversation" :aria-label="t('工单对话')"><button v-if="hasOlder" class="load-older" :disabled="loadingOlder||detailLoading" @click="older"><LoaderCircle v-if="loadingOlder" :size="16" class="spin"/>{{t('加载更早回复')}}</button><article v-for="reply in conversation" :key="reply.id" :class="['reply-row',{mine:reply.user_id===state?.me.id,internal:reply.internal}]"><div class="reply-avatar" aria-hidden="true">{{reply.sender.slice(0,1).toUpperCase()}}</div><div class="reply-content"><header><strong>{{reply.sender}}</strong><span v-if="reply.internal" class="internal-label"><LockKeyhole :size="13"/>{{t('内部备注')}}</span><time>{{stamp(reply.created)}}</time></header><div class="reply-bubble"><p>{{reply.body}}</p><div v-if="reply.attachments.length" class="reply-images"><a v-for="id in reply.attachments" :key="id" :href="imageURL(id)" target="_blank" rel="noopener noreferrer"><img :src="imageURL(id)" loading="lazy" :alt="t('工单图片，过期后不可查看')"/></a></div></div></div></article></div>
        </template>
        <form v-if="composerVisible" class="member-panel ticket-composer" @submit.prevent="submit"><div class="member-panel-title"><div><h2>{{creating?t('告诉我们遇到的问题'):internal?t('添加内部备注'):t('继续回复')}}</h2><p>{{creating?t('写清现象和发生时间，方便我们更快定位。'):internal?t('内部备注，仅管理员可见'):t('新的回复会保留在当前工单中。')}}</p></div><MessageSquare :size="22"/></div><fieldset :disabled="busy||uploading"><template v-if="creating"><div class="member-form-grid"><label>{{t('工单标题')}}<input v-model.trim="title" maxlength="120" required :placeholder="t('用一句话描述问题')"/></label><label>{{t('问题分类')}}<select v-model="category"><option value="account">{{t('账户与余额')}}</option><option value="order">{{t('订单与套餐')}}</option><option value="node">{{t('节点与线路')}}</option><option value="usage">{{t('用量问题')}}</option><option value="other">{{t('其他')}}</option></select></label></div></template><label>{{t('问题描述或回复')}}<textarea v-model.trim="body" maxlength="4000" rows="6" required :placeholder="t('描述问题、发生时间和已经尝试的操作…')"/></label><div class="composer-hint"><span>{{t('请勿提交密码、完整订阅链接或其他认证密钥')}}</span><span>{{body.length}} / 4000</span></div><details v-if="creating" class="member-disclosure" :open="!!orderID"><summary>{{t('关联订单或节点（选填）')}}</summary><div class="member-form-grid"><label>{{t('关联订单号（选填）')}}<input v-model.trim="orderID" maxlength="100"/></label><label>{{t('关联节点（选填）')}}<select v-model="resource"><option value="">{{t('不关联节点')}}</option><option v-for="item in resources" :key="item.site_id+'/'+item.node_id" :value="item.site_id+'/'+item.node_id">{{item.name}}</option></select></label></div></details><label v-if="owner&&!creating" class="inline-check internal-toggle"><input v-model="internal" type="checkbox"/>{{t('内部备注，仅管理员可见')}}</label><div class="attachment-toolbar"><label class="attachment-picker"><Paperclip :size="17"/><span>{{uploading?t('图片处理中…'):t('添加图片')}}</span><input type="file" accept="image/png,image/jpeg,.png,.jpg,.jpeg" multiple :disabled="busy||uploading||attachments.length>=3" :aria-label="t('添加图片')" @change="upload"/></label><span>{{t('PNG/JPG，每张最大 2 MiB，每次最多 3 张')}}</span></div><div v-if="attachments.length" class="composer-attachments"><div v-for="(id,index) in attachments" :key="id"><a :href="imageURL(id)" target="_blank" rel="noopener noreferrer"><img :src="imageURL(id)" :alt="t('待提交图片')"/></a><button type="button" :disabled="busy||uploading" :aria-label="t('移除图片')+' '+(index+1)" @click="attachments.splice(index,1)"><X :size="15"/>{{t('移除')}}</button></div></div><p v-if="attachments.length" class="attachment-expiry">{{t('未提交图片 15 分钟后失效，工单关闭后图片保留 90 天')}}</p></fieldset><div class="composer-footer"><p v-if="notice" class="composer-notice" role="status"><CircleCheck :size="16"/>{{notice}}</p><button class="primary" :disabled="busy||uploading||!body||(creating&&!title)"><LoaderCircle v-if="busy||uploading" :size="17" class="spin"/><Send v-else :size="17"/>{{uploading?t('图片处理中…'):busy?t('提交中…'):creating?t('提交问题'):internal?t('保存内部备注'):t('发送回复')}}</button></div></form>
      </div>
    </div>
  </section>
</template>
